function renderMarket(){
 const sorted=D.stocks.filter(s=>Number.isFinite(s.gun_pct)).sort((a,b)=>b.gun_pct-a.gun_pct);
 const mover=(items,title,direction,mode='change')=>`<div class="mover-panel"><h3><span class="${direction}">${direction==='up'?'↗':'↘'}</span> ${title}</h3><div class="mover-grid ${items.length>3?'five':''} ${items.length?'':'is-empty'}">${items.length?items.map(s=>`<button class="mover" data-detail="${s.kod}"><b><span class="mover-title">${companyLogo(s,'mover-logo')}${s.kod}</span><small>${mode==='score'?esc(actionOf(s)):money(s.fiyat,2)}</small></b><span class="${mode==='score'?(direction==='up'?'up':'down'):cls(s.gun_pct)} num">${mode==='score'?'Skor '+fmt(scoreOf(s),0):pct(s.gun_pct)}</span></button>`).join(''):`<div class="mover-empty"><b>${direction==='up'?'Yükselen hisse yok':'Düşen hisse yok'}</b><small>Seçili BIST 100 kapsamındaki tüm hisseler aynı yönde.</small></div>`}</div></div>`;
 const card=(name,price,unit,change,history,asOf,secondary='',glyph='',detail='')=>`<${detail?'button':'article'} class="market-card ${detail?'':'index-card'}"${detail?` data-detail="${detail}"`:''}><span class="card-label"><span>${name}</span><span class="card-tools">${glyph}<span class="freshness-wrap">${freshness(asOf)}</span></span></span><strong class="num">${fmt(price)}<span class="unit">${unit}</span></strong><span class="market-secondary ${secondary?'':'empty'}">${secondary||'—'}</span><span class="market-change ${cls(change)} num">${pct(change)}</span>${spark(history,change>=0?'var(--green)':'var(--red)')}</${detail?'button':'article'}>`;
 const benchmark=card('BIST 100',D.benchmark.price,'puan',D.benchmark.change,D.benchmark.history,D.benchmark.asOf,'','<span class="asset-glyph bist">'+assetGlyph('bist100')+'</span>','bist100');
 const macros=D.macros.map(m=>{const asOf=m.gram?.asOf||m.asOf;return card(m.name,m.gram?.price??m.price,m.gram?'₺ / gram':m.unit,m.gram?.change??m.change,m.gram?.history||m.history||[],asOf,m.gram?`${fmt(m.price)} USD / ons`:'',`<span class="asset-glyph ${m.id}">${assetGlyph(m.id)}</span>`,m.id);}).join('');
 const scored=D.stocks.filter(s=>Number.isFinite(scoreOf(s))).sort((a,b)=>scoreOf(b)-scoreOf(a));
 $('#main').innerHTML=pageHead('Piyasalar','Hisse, döviz ve değerli metaller')+`<section class="market-strip" aria-label="Piyasa özeti">${benchmark}${macros}</section><section class="movers">${mover(sorted.filter(s=>s.gun_pct>0).slice(0,5),'En çok yükselenler','up')}${mover([...sorted].reverse().filter(s=>s.gun_pct<0).slice(0,5),'En çok düşenler','down')}</section><section class="movers score-movers">${mover(scored.slice(0,5),'En yüksek skorlular','up','score')}${mover([...scored].reverse().slice(0,5),'En düşük skorlular','down','score')}</section><section class="panel"><div class="section-head"><div><h2>Hisseler</h2><small>Başlıkları sürükleyerek veya oklarla sütun sırasını değiştirin.</small></div><a href="#compare" class="chip">Hisse kıyasla ↗</a></div><div class="filters"><div class="field search"><label for="search">Hisse ara</label><input id="search" placeholder="Kod veya şirket adı" value="${esc(filter.search)}"></div><div class="field"><label for="sector">Sektör</label><select id="sector">${options(sectors(),filter.sector,'Tüm sektörler')}</select></div><div class="field"><label for="signal">Sinyal</label><select id="signal">${options(signals,filter.signal,'Tüm sinyaller')}</select></div><div class="field compact"><label for="minscore">En düşük skor</label><input id="minscore" type="number" min="0" max="100" value="${filter.min}"></div><label class="check" title="${D.stocks.some(s=>s.audit.status==='matched')?'Yalnızca ikinci kaynakla aynı tarih ve fiyat toleransında eşleşenler':'Bu veri yenilemesinde ikinci kaynak eşleşmesi bulunmuyor'}"><input id="verified" type="checkbox" ${filter.verified?'checked':''} ${D.stocks.some(s=>s.audit.status==='matched')?'':'disabled'}>2 kaynak uyumlu (${D.stocks.filter(s=>s.audit.status==='matched').length})</label><button id="clearfilter" class="quiet">Sıfırla</button></div><div id="stock-table"></div></section>`;
 if(D.aiAnalysis?.marketSummary)$('.page-head').insertAdjacentHTML('afterend',`<section class="ai-market-brief"><div><span class="ai-mark">A</span><b>Günlük analist değerlendirmesi</b><small>${esc(D.aiAnalysis.model||'Analiz motoru')} · ${stamp(D.aiAnalysis.generatedAt)}</small></div><p>${esc(D.aiAnalysis.marketSummary)}</p></section>`);
 $$('.market-card').forEach(card=>{const change=card.querySelector('.market-change'),sparkline=card.querySelector('.spark'),lower=document.createElement('div'),trend=document.createElement('div');lower.className='market-card-lower';trend.className='market-card-trend';lower.append(change);if(sparkline)trend.append(sparkline);lower.append(trend);card.append(lower);});
 $('#search').oninput=e=>{filter.search=e.target.value;stockPage=1;renderStockTable();};$('#sector').onchange=e=>{filter.sector=e.target.value;stockPage=1;renderStockTable();};$('#signal').onchange=e=>{filter.signal=e.target.value;stockPage=1;renderStockTable();};$('#minscore').oninput=e=>{filter.min=Math.max(0,Math.min(100,Number(e.target.value)||0));stockPage=1;renderStockTable();};$('#verified').onchange=e=>{filter.verified=e.target.checked;stockPage=1;renderStockTable();};$('#clearfilter').onclick=()=>{filter={search:'',sector:'',signal:'',min:0,verified:false};stockPage=1;renderMarket();};renderStockTable();bindDetails();
}
function matches(s,f){return (!f.search||(s.kod+' '+s.unvan).toLocaleLowerCase('tr').includes(f.search.toLocaleLowerCase('tr')))&&(!f.sector||s.sektor===f.sector)&&(!f.signal||actionOf(s)===f.signal)&&(!f.min||(scoreOf(s)!==null&&scoreOf(s)>=f.min))&&(!f.verified||s.audit.status==='matched');}
function renderStockTable(){
 const rows=D.stocks.filter(s=>matches(s,filter)).sort((a,b)=>{const av=Analytics.metrics[sort.key].get(a),bv=Analytics.metrics[sort.key].get(b);return av==null?1:bv==null?-1:(sort.desc?bv-av:av-bv);});
 const pages=Math.max(1,Math.ceil(rows.length/25));stockPage=Math.min(stockPage,pages);const visible=rows.slice((stockPage-1)*25,stockPage*25);
 const defs={
  company:{title:'Şirket',left:true,cell:s=>`<div class="stock-name">${companyLogo(s)}<button class="stock-link" data-detail="${s.kod}">${s.kod}<small>${esc(s.unvan)}</small></button></div>`},
  price:{title:'Fiyat',sort:'price',cell:s=>`<span class="num">${fmt(s.fiyat)}</span>`},change:{title:'Günlük',sort:'change',cell:s=>`<span class="num ${cls(s.gun_pct)}">${pct(s.gun_pct)}</span>`},
  score:{title:'Nihai skor',sort:'score',cell:s=>`<span class="score" title="Teknik ${fmt(s.analysis.score,0)} · haber düzeltmesi ${s.newsLayer?.adjustment>0?'+':''}${fmt(s.newsLayer?.adjustment||0,0)}">${metricHelp(fmt(scoreOf(s),0),'score')}<span class="score-track"><i style="width:${scoreOf(s)||0}%"></i></span></span>`},signal:{title:'Sinyal',cell:signalTag},
  fk:{title:'F/K',sort:'fk',cell:s=>metricHelp(`<span class="num">${fmt(s.fk)}</span>`,'fk')},roic:{title:'ROIC %',sort:'roic',cell:s=>metricHelp(`<span class="num">${fmt(s.roic)}</span>`,'roic')},alpha:{title:'Alfa 1Y %',sort:'alpha',cell:s=>metricHelp(`<span class="num ${cls(s.analysis.reg1?.alpha)}">${fmt(s.analysis.reg1?.alpha)}</span>`,'alpha')},beta:{title:'Beta 1Y',sort:'beta',cell:s=>metricHelp(`<span class="num">${fmt(s.analysis.reg1?.beta)}</span>`,'beta')},
  audit:{title:'Fiyat kontrolü',cell:auditTag},compare:{title:'Kıyasla',cell:s=>`<input type="checkbox" data-compare="${s.kod}" aria-label="${s.kod} kıyaslamaya ekle" ${selected.has(s.kod)?'checked':''}>`}
 };
 const head=(key,i)=>{const d=defs[key],label=d.sort?`<button data-sort="${d.sort}">${d.title}${sort.key===d.sort?(sort.desc?' ↓':' ↑'):''}</button>`:`<span>${d.title}</span>`;return `<th class="market-column ${d.left?'left':''}" draggable="true" data-market-column="${key}" title="Sürükleyerek sırala"><div class="column-title">${label}<span class="column-actions"><button data-mcolmove="${i}:left" aria-label="${d.title} sütununu sola taşı" ${i===0?'disabled':''}>←</button><button data-mcolmove="${i}:right" aria-label="${d.title} sütununu sağa taşı" ${i===marketColumns.length-1?'disabled':''}>→</button></span></div></th>`;};
 $('#stock-table').innerHTML=`<div class="table-wrap"><table class="market-table"><thead><tr>${marketColumns.map(head).join('')}</tr></thead><tbody>${visible.map(s=>`<tr>${marketColumns.map(key=>`<td class="${defs[key].left?'left':''}">${defs[key].cell(s)}</td>`).join('')}</tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">Bu filtrelerde hisse bulunamadı.</div>':''}</div><div class="table-bottom"><span>${rows.length} / ${D.stocks.length} hisse · Sayfa ${stockPage}/${pages}</span><div class="inline-actions"><button id="stock-prev" ${stockPage===1?'disabled':''}>←</button><button id="stock-next" ${stockPage===pages?'disabled':''}>→</button><a href="#compare">${selected.size} hisse seçili · Kıyaslamayı aç →</a></div></div>`;
 $$('[data-sort]').forEach(b=>b.onclick=e=>{e.stopPropagation();sort={key:b.dataset.sort,desc:sort.key===b.dataset.sort?!sort.desc:true};stockPage=1;renderStockTable();});$$('[data-mcolmove]').forEach(b=>b.onclick=e=>{e.stopPropagation();const [ix,dir]=b.dataset.mcolmove.split(':'),i=+ix,j=i+(dir==='left'?-1:1);[marketColumns[i],marketColumns[j]]=[marketColumns[j],marketColumns[i]];saveMarketColumns();renderStockTable();});$$('[data-market-column]').forEach(th=>{th.ondragstart=e=>e.dataTransfer.setData('text/plain',th.dataset.marketColumn);th.ondragover=e=>e.preventDefault();th.ondrop=e=>{e.preventDefault();const from=e.dataTransfer.getData('text/plain'),to=th.dataset.marketColumn;if(!marketColumns.includes(from)||from===to)return;marketColumns.splice(marketColumns.indexOf(from),1);marketColumns.splice(marketColumns.indexOf(to),0,from);saveMarketColumns();renderStockTable();};});$('#stock-prev').onclick=()=>{stockPage--;renderStockTable();};$('#stock-next').onclick=()=>{stockPage++;renderStockTable();};bindCompareChecks();bindDetails();bindMetricTips();
}
