function renderGuide(){
 $('#main').innerHTML=pageHead('Skor rehberi','Göstergeler, haber etkisi ve veri sınırları',`<span class="tag blue">Model ${esc(D.modelVersion)}</span>`)+`<div class="guide-grid"><section class="panel"><h2>Alfa nedir?</h2><p>Hissenin günlük getirisi ile BIST 100 getirisi arasındaki doğrusal modelde, endeks hareketiyle açıklanamayan ortalama günlük getiridir. Gösterilen değer yıllıklandırılır.</p><div class="formula">Hisse getirisi = günlük alfa + beta × BIST 100 getirisi + hata<br>Yıllık alfa (%) = günlük alfa × 252 × 100</div><p>Risksiz faiz ve temettü bu hesapta yoktur; geçmişteki ilişki gelecekteki getiriyi göstermez.</p></section><section class="panel"><h2>Beta nedir?</h2><p>Hissenin BIST 100 günlük getirisine tarihsel duyarlılığıdır. Beta 1,2, örneklemde endeks %1 değiştiğinde modelin hisse için yaklaşık %1,2 aynı yönlü hareket hesapladığını anlatır.</p><div class="formula">Beta = Cov(hisse, BIST 100) ÷ Var(BIST 100)</div><p>Teknik skor için en az 120 tarih eşleşmeli günlük getiri gerekir.</p></section><section class="panel guide-wide"><h2>Bugünkü skor nasıl hesaplanır?</h2><p>Teknik skor 50 puandan başlar. 63 seanslık momentum ×1,4 etkisi ±12 puanla, 1 yıllık alfa ×0,12 etkisi ±6 puanla sınırlanır. Beta &gt;1,5 ise −5; 0–0,7 ise +3 puan uygulanır. Sonuç 0–100'e yuvarlanır.</p><p>ROIC, F/K ve bilanço kartlarda ayrıca gösterilir; mevcut bulut teknik skoruna otomatik eklenmez. Eksik fiyat geçmişinde skor gösterilmez.</p><div class="callout">Nihai skor ≥75: AL adayı · 45–74: BEKLE · &lt;45: SAT adayı. Bu etiketler sanal izleme sinyalidir, emir değildir.</div></section><section class="panel"><h2>Haber puanı</h2><p>Son 7 günün şirketle eşleşen, tarihi belirli haber başlıkları olumlu veya olumsuz yönde puanlanır. Başlıklar tekilleştirilir; teknik skora toplam en fazla ±10 puan eklenir. Her haberde tarih, kaynak, yön ve gerekçe görünür.</p><p>Bu başlık ve kurala dayalı ön analizdir. Haberin gerçekleşen fiyat etkisi ölçülmez. KAP belgeleri bu günlük haber skoruna otomatik dahil değildir; kullanılabilir olduğunda ayrıntıda ayrıca gösterilir.</p></section><section class="panel"><h2>Kaynak ve güncellik</h2><p>Günlük fiyat ve geçmiş için Yahoo Finance kullanılır. Fintables ile eşzamanlı ikinci fiyat doğrulaması bu bulut akışında etkin değildir; fiyatlar tek kaynak olarak işaretlenir. Fon/hisse geçmişi varlığa göre değişir.</p><p>Bulut fiyatları pazartesi–cumartesi 10.00'da, haberleri 10.10'da tarar. Kaynak saati ve son tarama tarihi ekranda görünür. Üretken yapay zekâ modeli şu an çalışmıyor; açıklamalar kural tabanlıdır.</p></section></div>`;
}
const saveSnapshot=()=>window.AtlasCache?.write('bist',accessKey(),{data:D,portfolio:PORT,user:USER});
async function init(){
 BIST_PORTFOLIO_SYNCING=true;
 const loader=$('#initial-loading'),timer=setTimeout(()=>{if(loader?.isConnected)loader.hidden=false;},400);
 const cached=await window.AtlasCache?.read('bist',accessKey());
 if(cached?.value?.data?.stocks?.length){D=cached.value.data;PORT=cached.value.portfolio||null;USER=cached.value.user||USER;clearTimeout(timer);route();}
 try{
  if(!D||!window.AtlasCache.isFresh(cached)){
   const accountPromise=Promise.all([api('/api/portfolio'),api('/api/user-state')]).catch(error=>({error}));
   const next=await api('/api/data');
   if(!next.stocks?.length)throw Error('Henüz veri hazırlanmadı. Biraz sonra yenileyin.');
   D=next;if(location.hash!=='#simulation')route();
   const loaded=await accountPromise;if(loaded.error)throw loaded.error;
   [PORT,USER]=loaded;BIST_PORTFOLIO_SYNCING=false;
   if(location.hash==='#simulation'||location.hash==='#intelligence')route();
  }else{
   [PORT,USER]=await Promise.all([api('/api/portfolio'),api('/api/user-state')]);BIST_PORTFOLIO_SYNCING=false;
   if(location.hash==='#simulation')renderSimulation();
  }
  saveSnapshot();
 }catch(e){if(D){if(location.hash==='#simulation'){$('#main').innerHTML='<div class="empty">Bulut portföyü alınamadı. <button id="retry">Tekrar dene</button></div>';$('#retry').onclick=init;}else toast('Son kayıt gösteriliyor; bulut bağlantısı yenilenemedi.');}else{$('#main').innerHTML=`<div class="empty">${esc(e.message)}<br><button id="retry" style="margin-top:18px">Tekrar dene</button></div>`;$('#retry').onclick=init;}}
 finally{clearTimeout(timer);}
}
